import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.map.js";
import { API, graphqlOperation } from "aws-amplify";
import { quotation_billing_entities } from "@/graphql/mutations.js";
import { Auth } from "aws-amplify";
import { uploadToS3 } from "@/mixins/S3PutStorageFile.js";
export default {
  name: "AddEntityDialog",
  props: {
    modelValue: {
      type: Boolean,
      default: false
    }
  },
  emits: ["update:modelValue", "save", "successMsg", "errorMsg"],
  data() {
    return {
      saving: false,
      showBusinessDetails: false,
      bucketUrls: {
        logo: null,
        signature: null,
        qrCode: null
      },
      entityForm: {
        name: "",
        gstNo: "",
        phoneNo: "",
        emailId: "",
        logo: null,
        logoFile: null,
        qrCode: null,
        qrCodeFile: null,
        businessAddress: "",
        pincode: "",
        state: "",
        businessType: "",
        businessCategory: "",
        businessDescription: "",
        signature: null,
        signatureFile: null
      },
      businessTypes: [{
        title: "Retail",
        value: "retail"
      }, {
        title: "Wholesale",
        value: "wholesale"
      }, {
        title: "Distributor",
        value: "distributor"
      }, {
        title: "Other",
        value: "other"
      }, {
        title: "Service",
        value: "service"
      }, {
        title: "Manufacturer",
        value: "manufacturer"
      }],
      indianStates: ["Andhra Pradesh", "Arunachal Pradesh", "Assam", "Bihar", "Chhattisgarh", "Goa", "Gujarat", "Haryana", "Himachal Pradesh", "Jharkhand", "Karnataka", "Kerala", "Madhya Pradesh", "Maharashtra", "Manipur", "Meghalaya", "Mizoram", "Nagaland", "Odisha", "Punjab", "Rajasthan", "Sikkim", "Tamil Nadu", "Telangana", "Tripura", "Uttar Pradesh", "Uttarakhand", "West Bengal", "Delhi", "Jammu and Kashmir", "Ladakh"],
      // Validation rules
      gstRules: [v => !v || /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$/.test(v) || "Invalid GST number format"],
      phoneRules: [v => !v || /^[6-9]\d{9}$/.test(v) || "Invalid phone number (10 digits starting with 6-9)"],
      emailRules: [v => !v || /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v) || "Invalid email format"],
      pincodeRules: [v => !v || /^[1-9][0-9]{5}$/.test(v) || "Invalid pincode (6 digits)"]
    };
  },
  computed: {
    dialog: {
      get() {
        return this.modelValue;
      },
      set(value) {
        this.$emit("update:modelValue", value);
      }
    }
  },
  watch: {
    modelValue(newVal) {
      if (newVal) {
        this.resetForm();
      }
    },
    "entityForm.logoFile": {
      handler(newFile) {
        if (newFile) {
          this.handleFileUpload(newFile, "logo");
        } else {
          this.entityForm.logo = null;
        }
      },
      immediate: false
    },
    "entityForm.signatureFile": {
      handler(newFile) {
        if (newFile) {
          this.handleFileUpload(newFile, "signature");
        } else {
          this.entityForm.signature = null;
        }
      },
      immediate: false
    },
    "entityForm.qrCodeFile": {
      handler(newFile) {
        if (newFile) {
          this.handleFileUpload(newFile, "qrCode");
        } else {
          this.entityForm.qrCode = null;
        }
      },
      immediate: false
    }
  },
  methods: {
    resetForm() {
      this.entityForm = {
        name: "",
        gstNo: "",
        phoneNo: "",
        emailId: "",
        logo: null,
        logoFile: null,
        qrCode: null,
        qrCodeFile: null,
        businessAddress: "",
        pincode: "",
        state: "",
        businessType: "",
        businessCategory: "",
        businessDescription: "",
        signature: null,
        signatureFile: null
      };
      this.showBusinessDetails = false;
      this.bucketUrls = {
        logo: null,
        signature: null,
        qrCode: null
      };
      if (this.$refs.form) {
        this.$refs.form.resetValidation();
      }
    },
    closeDialog() {
      this.dialog = false;
      this.resetForm();
    },
    handleFileUpload(file, type) {
      // console.log("handleFileUpload called:", file, type);
      if (file && typeof file === "object" && file.type && file.type.startsWith("image/")) {
        const reader = new FileReader();
        reader.onload = e => {
          //  console.log("FileReader result:", e.target.result);
          this.entityForm[type] = e.target.result;
        };
        reader.onerror = error => {
          console.error("FileReader error:", error);
        };
        reader.readAsDataURL(file);
      } else {
        // Clear the preview if no valid file is provided
        this.entityForm[type] = null;
      }
    },
    clearFile(type) {
      this.entityForm[`${type}File`] = null;
      this.entityForm[type] = null;
      this.bucketUrls[type] = null;
    },
    convertToPngFormat(filename) {
      if (!filename) return "";
      return filename.replace(/\.[^.]+$/, ".jpg");
    },
    async upload_new_func(file, type) {
      let concertedfile = this.convertToPngFormat(file.name);
      await Auth.currentCredentials();
      const orgDetails = this.$store.getters.GetOrgDetails;
      const s3_details = {
        bucket_name: "stichh-medias",
        region: "us-east-1"
      };
      const key = [`quotations/${orgDetails.organization.organization_id}/${Date.now()}-${this.replaceSpecialCharacters(concertedfile)}`];
      try {
        const fileUrl = await uploadToS3(file, s3_details, key);
        if (fileUrl) {
          return this.bucketUrls[type] = fileUrl;
        }
      } catch (err) {
        this.$emit("errorMsg", "Upload failed. Check console");
        this.saving = false;
      }
    },
    async get_file() {
      this.bucketUrls = {
        logo: null,
        signature: null,
        qrCode: null
      };
      let files = [{
        file: this.entityForm.logoFile,
        type: "logo"
      }, {
        file: this.entityForm.signatureFile,
        type: "signature"
      }, {
        file: this.entityForm.qrCodeFile,
        type: "qrCode"
      }].filter(item => item.file && typeof item.file === "object" && item.file.type && item.file.type.startsWith("image/"));
      if (files.length === 0) {
        // No files to upload, proceed with saving entity data
        this.saveEntityData();
        return;
      }
      let uploadPromises = files.map(({
        file,
        type
      }) => {
        return new Promise((resolve, reject) => {
          if (!file || typeof file !== "object" || !file.type || !file.type.startsWith("image/")) {
            reject(new Error(`Invalid file for type: ${type}`));
            return;
          }
          const fr = new FileReader();
          fr.onload = event => {
            this.upload_new_func(file, type).then(resolve).catch(reject);
          };
          fr.onerror = () => {
            reject(new Error(`Failed to read file for type: ${type}`));
          };
          fr.readAsDataURL(file);
        });
      });
      Promise.all(uploadPromises).then(() => {
        this.saveEntityData();
      }).catch(error => {
        console.error("Error uploading images:", error);
        this.saving = false;
        this.$emit("errorMsg", "Error uploading files. Please try again.");
      });
    },
    async validateAndUpload() {
      const {
        valid
      } = await this.$refs.form.validate();

      // Additional validation for logo and signature
      if (!this.entityForm.logoFile) {
        this.$emit("errorMsg", "Please upload an Entity Logo.");
        return;
      }
      if (valid) {
        this.saving = true;
        this.get_file();
      } else {
        this.$emit("errorMsg", "Please fill in all required fields (Entity Name and Logo are mandatory).");
      }
    },
    replaceSpecialCharacters(filename) {
      return filename.replace(/[^a-zA-Z0-9.]/g, "_");
    },
    async saveEntityData() {
      var imageDetails = this.bucketUrls;
      try {
        let result = await API.graphql(graphqlOperation(quotation_billing_entities, {
          input: {
            action_type: "CREATE",
            entity_name: this.entityForm.name,
            entity_type: this.entityForm.businessType || "",
            enitity_category: this.entityForm.businessCategory || "",
            entity_description: this.entityForm.businessDescription || "",
            is_default: false,
            entity_status: "ACTIVE",
            entity_logo: imageDetails.logo,
            entity_seal_signature: imageDetails.signature,
            entity_qr_code: imageDetails.qrCode,
            entity_address: this.entityForm.businessAddress || "",
            entity_contact_no: this.entityForm.phoneNo || "",
            entity_gst: this.entityForm.gstNo || "",
            entity_owner_email: this.entityForm.emailId || "",
            entity_pincode: this.entityForm.pincode || "",
            entity_state: this.entityForm.state || ""
          }
        }));
        this.saving = false;
        var response = JSON.parse(result.data.quotation_billing_entities);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.saving = false;
          this.$refs.form.resetValidation();
          this.$refs.form.reset();
          this.entityForm.logo = "";
          this.entityForm.signature = "";
          this.entityForm.qrCode = "";
          this.closeDialog();
        } else {
          this.saving = false;
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        console.log(error);
        this.saving = false;
        this.$emit("errorMsg", error.errors[0].message || "Error creating entity. Please try again.");
      }
    }
  }
};
